function example() {
  const users = [
    { value: '1', label: 'John Doe', email: 'john@example.com' },
    { value: '2', label: 'Jane Smith', email: 'jane@example.com' },
    { value: '3', label: 'Bob Johnson', email: 'bob@example.com' },
  ];
  const [selected, setSelected] = useState<(typeof users)[number] | null>(null);

  return (
    <Block>
      <Autocomplete
        data={users}
        field="label"
        placeholder="Search users..."
        openOnFocus
        onSelect={item =>
          setSelected(
            users.find(
              u => u.value === (typeof item === 'string' ? item : item?.value)
            ) ?? null
          )
        }
      />
      {selected && (
        <Paragraph mt="2">
          Selected: {selected.label} ({selected.email})
        </Paragraph>
      )}
    </Block>
  );
}

function example() {
  const users = [
    { value: '1', label: 'John Doe', role: 'Admin' },
    { value: '2', label: 'Jane Smith', role: 'Editor' },
    { value: '3', label: 'Bob Johnson', role: 'Viewer' },
  ];

  return (
    <Autocomplete
      data={users}
      field="label"
      placeholder="Search users..."
      openOnFocus
      itemTemplate={item => {
        const user = users.find(
          u => u.value === (typeof item === 'string' ? item : item.value)
        );
        return (
          <Block display="flex" justifyContent="space-between">
            <Span>{user?.label}</Span>
            <Tag color="info" isLight>
              {user?.role}
            </Tag>
          </Block>
        );
      }}
    />
  );
}

